"""Analyses worlds generated by generate.py from their region files.

    python3 tools/worldcheck/analyze.py run/vl_a                 # one world
    python3 tools/worldcheck/analyze.py run/vl_a run/vanilla_a   # plus a block-by-block comparison

Reports the generated section range, the bedrock floor, block composition per height band and surface
heights; with two worlds, the fraction of identical blocks, biomes and surface heights in the Y range
both worlds share. Only the chunk square recorded in worldcheck.json is read, minus the probe column.
"""
import json
import math
import os
import sys
from collections import Counter

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from anvil import read_chunk, section_biomes, section_blocks  # noqa: E402

AIR = {"minecraft:air", "minecraft:cave_air", "minecraft:void_air"}
CATEGORIES = {
    "minecraft:stone": "stone", "minecraft:deepslate": "deepslate", "minecraft:water": "water",
    "minecraft:lava": "lava", "minecraft:bedrock": "bedrock",
}


def category(name):
    return "air" if name in AIR else CATEGORIES.get(name, "other")


class World:
    def __init__(self, path):
        self.path = path
        with open(os.path.join(path, "worldcheck.json")) as f:
            self.meta = json.load(f)
        r = self.meta["radius"]
        lo_x, lo_z, hi_x, hi_z = self.meta.get("chunk_range", [-r, -r, r - 1, r - 1])
        self.probe = tuple(self.meta["probe_column"])
        self.chunks = {}
        for cx in range(lo_x, hi_x + 1):
            for cz in range(lo_z, hi_z + 1):
                nbt = read_chunk(os.path.join(path, "region"), cx, cz)
                if nbt is None or nbt.get("Status") != "minecraft:full":
                    raise SystemExit("chunk %d,%d of %s is missing or not fully generated" % (cx, cz, path))
                sections = {s["Y"]: s for s in nbt["sections"] if "block_states" in s}
                self.chunks[(cx, cz)] = (nbt, sections)
        ys = [y for _, secs in self.chunks.values() for y in secs]
        self.min_section, self.max_section = min(ys), max(ys)
        self.min_y, self.max_y = self.min_section * 16, self.max_section * 16 + 15

    def is_probe(self, cx, cz, lx, lz):
        return (cx * 16 + lx, cz * 16 + lz) == self.probe

    def heightmap(self, nbt, name):
        """256 surface Y values (top block of the heightmap type), index = z*16 + x."""
        bits = math.ceil(math.log2(self.max_y - self.min_y + 2))
        per_long, mask, out = 64 // bits, (1 << bits) - 1, []
        for value in nbt["Heightmaps"][name]:
            value &= 0xFFFFFFFFFFFFFFFF
            for _ in range(per_long):
                if len(out) < 256:
                    out.append((value & mask) + self.min_y - 1)
                value >>= bits
        return out


def bands(world):
    starts = [world.min_y, -64, 0, 63, 256]
    out = []
    for i, start in enumerate(starts):
        end = starts[i + 1] - 1 if i + 1 < len(starts) else world.max_y
        lo, hi = max(start, world.min_y), min(end, world.max_y)
        if lo <= hi:
            out.append((lo, hi))
    return out


def band_of(band_list, y):
    for b in band_list:
        if b[0] <= y <= b[1]:
            return b
    return None


def describe(world):
    print("== %s  (%s, seed %s)" % (world.path, world.meta["level_type"], world.meta["seed"]))
    print("chunks: %d fully generated; sections Y %d..%d -> blocks Y %d..%d"
          % (len(world.chunks), world.min_section, world.max_section, world.min_y, world.max_y))
    print("setblock probes:", {y: msg.strip() for y, msg in world.meta["setblock_probes"].items()})

    band_list = bands(world)
    composition = {b: Counter() for b in band_list}
    floor = Counter()
    bedrock_layers = Counter()
    highest_solid = world.min_y
    for (cx, cz), (nbt, sections) in world.chunks.items():
        for sy, section in sections.items():
            palette = [p["Name"] for p in section["block_states"]["palette"]]
            if len(palette) == 1:
                y_lo = sy * 16
                for y in range(y_lo, y_lo + 16):
                    composition[band_of(band_list, y)][category(palette[0])] += 256
                if palette[0] not in AIR:
                    highest_solid = max(highest_solid, y_lo + 15)
                if sy == world.min_section:
                    floor[palette[0]] += 256
                continue
            blocks = section_blocks(section)
            for i, name in enumerate(blocks):
                y = sy * 16 + (i >> 8)
                lx, lz = i & 15, (i >> 4) & 15
                if world.is_probe(cx, cz, lx, lz):
                    continue
                composition[band_of(band_list, y)][category(name)] += 1
                if name not in AIR and y > highest_solid:
                    highest_solid = y
                if y == world.min_y:
                    floor[name] += 1
                if name == "minecraft:bedrock":
                    bedrock_layers[y] += 1

    columns = len(world.chunks) * 256
    print("floor (Y %d): %s of %d columns" % (world.min_y, dict(floor), columns))
    print("bedrock blocks per layer:", dict(sorted(bedrock_layers.items())))
    print("highest non-air block: Y %d" % highest_solid)
    print("composition by band (%):")
    for b in band_list:
        total = sum(composition[b].values())
        parts = ", ".join("%s %.1f" % (k, 100.0 * v / total) for k, v in composition[b].most_common())
        print("  Y %5d..%-4d %s" % (b[0], b[1], parts))
    for name in ("WORLD_SURFACE", "OCEAN_FLOOR"):
        values = [h for (cx, cz), (nbt, _) in world.chunks.items() for i, h in enumerate(world.heightmap(nbt, name))
                  if not world.is_probe(cx, cz, i & 15, i >> 4)]
        print("%s: min %d, max %d, mean %.1f" % (name, min(values), max(values), sum(values) / len(values)))


def compare(a, b):
    print("== compare %s vs %s" % (a.path, b.path))
    lo = max(a.min_section, b.min_section)
    hi = min(a.max_section, b.max_section)
    print("shared sections Y %d..%d (blocks Y %d..%d)" % (lo, hi, lo * 16, hi * 16 + 15))
    same_blocks = total_blocks = same_biomes = total_biomes = 0
    diffs = Counter()
    diff_by_y = Counter()
    for key in a.chunks:
        (_, sa), (_, sb) = a.chunks[key], b.chunks[key]
        for sy in range(lo, hi + 1):
            if sa[sy]["biomes"] == sb[sy]["biomes"]:
                same_biomes += 64
            else:
                same_biomes += sum(x == y for x, y in zip(section_biomes(sa[sy]), section_biomes(sb[sy])))
            total_biomes += 64
            if sa[sy]["block_states"] == sb[sy]["block_states"]:
                same_blocks += 4096
                total_blocks += 4096
                continue
            for i, (x, y) in enumerate(zip(section_blocks(sa[sy]), section_blocks(sb[sy]))):
                if a.is_probe(key[0], key[1], i & 15, (i >> 4) & 15):
                    continue
                total_blocks += 1
                if x == y:
                    same_blocks += 1
                else:
                    diffs[(x, y)] += 1
                    diff_by_y[(sy * 16 + (i >> 8)) // 32 * 32] += 1
    print("identical blocks: %.4f%% (%d of %d differ)" % (100.0 * same_blocks / total_blocks, total_blocks - same_blocks, total_blocks))
    print("identical biomes: %.4f%%" % (100.0 * same_biomes / total_biomes))
    if diffs:
        print("most common differences (first world -> second world):")
        for (x, y), n in diffs.most_common(12):
            print("  %8d  %s -> %s" % (n, x, y))
        print("differing blocks by 32-block Y slice:", dict(sorted(diff_by_y.items())))
    for name in ("WORLD_SURFACE", "OCEAN_FLOOR"):
        same = total = worst = 0
        for key, (nbt_a, _) in a.chunks.items():
            ha, hb = a.heightmap(nbt_a, name), b.heightmap(b.chunks[key][0], name)
            for i, (x, y) in enumerate(zip(ha, hb)):
                if a.is_probe(key[0], key[1], i & 15, i >> 4):
                    continue
                total += 1
                same += x == y
                worst = max(worst, abs(x - y))
        print("%s identical in %.2f%% of columns, max difference %d blocks" % (name, 100.0 * same / total, worst))


def main():
    worlds = [World(p) for p in sys.argv[1:]]
    if not worlds:
        raise SystemExit(__doc__)
    for w in worlds:
        describe(w)
        print()
    if len(worlds) == 2:
        compare(*worlds)


if __name__ == "__main__":
    main()
